#include "profile.h"

#include <cstdio>
#include <cstdlib>
#include <fstream>
#include <mutex>
#include <sstream>

#include "json_lite.h"

namespace aegis::hw {

namespace detail {
// Generated by CMake from include/aegis/arch/sm_*.json (arch_profiles.cpp in the build tree).
struct EmbeddedProfile {
  int arch;
  const char* json;
};
extern const EmbeddedProfile kEmbeddedProfiles[];
extern const int kEmbeddedProfileCount;
}  // namespace detail

namespace {

std::string fmt_num(double v) {
  char b[32];
  std::snprintf(b, sizeof b, "%.15g", v);
  return b;
}

bool read_text(const std::string& path, std::string* out) {
  std::ifstream f(path);
  if (!f) return false;
  std::stringstream ss;
  ss << f.rdbuf();
  *out = ss.str();
  return true;
}

// The file for d: $AEGIS_PROFILE_DIR first, then the embedded one. Every file
// that was tried and did not match adds its reason.
Profile resolve(const DeviceLimits& d) {
  std::string why;
  const std::string file = "sm_" + std::to_string(d.arch) + ".json";
  if (const char* dir = std::getenv("AEGIS_PROFILE_DIR"); dir && *dir) {
    std::string text;
    const std::string path = std::string(dir) + "/" + file;
    if (read_text(path, &text)) {
      Profile p = match_profile(d, text, path);
      if (p.measured) return p;
      why = p.mismatch;
    }
  }
  const char* emb = std::getenv("AEGIS_PROFILE_EMBEDDED");
  const bool use_embedded = !(emb && std::string(emb) == "0");
  const std::string text = use_embedded ? embedded_profile(d.arch) : "";
  if (!use_embedded) {
    why += (why.empty() ? "" : "; ") + std::string("embedded profiles off (AEGIS_PROFILE_EMBEDDED=0)");
  } else if (!text.empty()) {
    Profile p = match_profile(d, text, "embedded include/aegis/arch/" + file);
    if (p.measured) return p;
    why += (why.empty() ? "" : "; ") + p.mismatch;
  } else {
    why += (why.empty() ? "" : "; ") + std::string("no arch profile for sm_") + std::to_string(d.arch);
  }
  return unmeasured_profile(d, why);
}

void warn_once(const Profile& p) {
  std::fprintf(stderr,
               "aegis: unmeasured device %s (sm_%d, %d SMs): %s. Using conservative defaults from the device "
               "query; run aegis-perf calibrate.\n",
               p.device.c_str(), p.arch, p.sm_count, p.mismatch.c_str());
}

}  // namespace

std::string embedded_profile(int arch) {
  for (int i = 0; i < detail::kEmbeddedProfileCount; ++i)
    if (detail::kEmbeddedProfiles[i].arch == arch) return detail::kEmbeddedProfiles[i].json;
  return "";
}

Profile unmeasured_profile(const DeviceLimits& d, const std::string& why) {
  Profile p;
  p.measured = false;
  p.source = "defaults: device query";
  p.mismatch = why;
  p.device = d.name;
  p.arch = d.arch;
  p.sm_count = d.sm_count;
  p.l2_bytes = int64_t(d.l2_bytes);
  return p;
}

Profile match_profile(const DeviceLimits& d, const std::string& text, const std::string& source) {
  json::Value v;
  if (!json::parse(text, &v)) return unmeasured_profile(d, source + ": not valid JSON");
  std::string bad;
  auto num_eq = [&](const char* key, double want) {
    const json::Value& f = v[key];
    if (!f.is_number() || f.num != want)
      bad += std::string(bad.empty() ? "" : ", ") + key + " " + (f.is_number() ? fmt_num(f.num) : "missing") +
             " != device " + fmt_num(want);
  };
  num_eq("sm_arch", d.arch);
  num_eq("sm_count", d.sm_count);
  num_eq("l2_bytes", double(d.l2_bytes));
  if (!v["device"].is_string() || v["device"].str != d.name)
    bad += std::string(bad.empty() ? "" : ", ") + "device \"" + v["device"].str + "\" != \"" + d.name + "\"";
  if (!bad.empty()) return unmeasured_profile(d, source + ": " + bad);
  Profile p;
  p.measured = true;
  p.source = source;
  p.device = d.name;
  p.arch = d.arch;
  p.sm_count = d.sm_count;
  p.l2_bytes = int64_t(d.l2_bytes);
  p.read_bw_gbps = v["read_bw_gbps"]["value"].number_or(-1);
  p.copy_bw_gbps = v["copy_bw_gbps"]["value"].number_or(-1);
  p.mma_peak_tflops = v["mma_peak"]["tflops"].number_or(-1);
  p.dram_latency_cycles = v["dram_latency"]["cycles"].number_or(-1);
  p.l2_latency_cycles = v["l2_latency"]["cycles"].number_or(-1);
  p.latency_ref_clock_mhz = v["dram_latency"]["ref_clock_mhz"].number_or(-1);
  return p;
}

const Profile& current_profile() {
  static const Profile kNoDevice = [] {
    Profile p;
    p.source = "defaults: no device";
    p.mismatch = "no CUDA device";
    return p;
  }();
  const DeviceLimits* d = current();
  if (!d) return kNoDevice;
  if (d->simulated) {
    thread_local Profile sim;
    sim = resolve(*d);
    return sim;
  }
  struct Slot {
    std::once_flag once;
    Profile p;
  };
  static Slot slots[kMaxCachedDevices];
  if (d->device < 0 || d->device >= kMaxCachedDevices) {
    thread_local Profile uncached;
    uncached = resolve(*d);
    return uncached;
  }
  Slot& s = slots[d->device];
  std::call_once(s.once, [&] {
    s.p = resolve(*d);
    if (!s.p.measured) warn_once(s.p);
  });
  return s.p;
}

}  // namespace aegis::hw
